begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select plan(27);
create temporary table workflow_ids (task_id uuid,application_id uuid,contract_id uuid);
grant all on workflow_ids to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub',md5('campusgig:client:1')::uuid::text,true);
insert into workflow_ids(task_id) select public.publish_task('SQL test project','Deliver one reviewable artifact with documented choices.',725.50,now()+interval '7 days','{"hoursMin":2,"hoursMax":4,"deliverables":["Artifact"],"requirements":["Docs"]}','fallback',array['react']);
select is((select count(*)::integer from workflow_ids),1,'client publishes task');
select is(public.publish_task('Retry test task','Deliver one reviewable artifact with documented choices.',500,now()+interval '7 days','{}','fallback',array[]::text[],md5('campusgig:test:request')::uuid),
 public.publish_task('Retry test task','Deliver one reviewable artifact with documented choices.',500,now()+interval '7 days','{}','fallback',array[]::text[],md5('campusgig:test:request')::uuid),'signed request nonce idempotent publish');
select throws_ok('select public.publish_task(''Invalid price task'',''Deliver one reviewable artifact with documented choices.'',1000001,now()+interval ''7 days'',''{}'',''fallback'',array[]::text[])','P0001',null,'price maximum enforced');
select throws_ok('select public.publish_task(''Invalid AI task'',''Deliver one reviewable artifact with documented choices.'',500,now()+interval ''7 days'',''{"hoursMin":5,"hoursMax":2}'',''fallback'',array[]::text[])','P0001',null,'analysis hours crossbounds enforced');
select throws_ok('select public.publish_task(''Invalid skills task'',''Deliver one reviewable artifact with documented choices.'',500,now()+interval ''7 days'',''{}'',''fallback'',array[''React.js''])','P0001',null,'publish requires canonical skill slugs');
select set_config('request.jwt.claim.sub',md5('campusgig:student:2')::uuid::text,true);
update workflow_ids set application_id=public.apply_to_task(task_id,'I will deliver a documented artifact for this project.');
select is((select match_score from public.applications where id=(select application_id from workflow_ids)),15,'SQL match components deterministic');
select set_config('request.jwt.claim.sub',md5('campusgig:client:2')::uuid::text,true);
select throws_ok('select public.hire_application(application_id) from workflow_ids','42501',null,'nonowner client cannot hire');
select set_config('request.jwt.claim.sub',md5('campusgig:client:1')::uuid::text,true);
update workflow_ids set contract_id=public.hire_application(application_id);
select is((select status from public.tasks where id=(select task_id from workflow_ids)),'IN_PROGRESS','task hired atomically');
select is((select amount from public.payments where contract_id=(select contract_id from workflow_ids)),725.50::numeric,'payment holds confirmed price');
select is((select status from public.payments where contract_id=(select contract_id from workflow_ids)),'HELD','simulated funds held');
select throws_ok('select public.hire_application(application_id) from workflow_ids','P0001',null,'second hire prevented');
select throws_ok('select public.approve_work(contract_id) from workflow_ids','P0001',null,'cannot approve before submission');
select set_config('request.jwt.claim.sub',md5('campusgig:student:2')::uuid::text,true);
select lives_ok('select public.submit_work(contract_id,''https://example.com/work/first'',''First delivery with documented decisions.'') from workflow_ids','first submission');
select throws_ok('select public.submit_work(contract_id,''https://example.com/work/duplicate'',''Duplicate delivery with documented decisions.'') from workflow_ids','P0001',null,'cannot duplicate pending submission');
select set_config('request.jwt.claim.sub',md5('campusgig:client:1')::uuid::text,true);
select lives_ok('select public.request_revision(contract_id,''Please improve the accessible focus indicators.'') from workflow_ids','client requests revision');
select is((select revision_count from public.contracts where id=(select contract_id from workflow_ids)),1,'one revision tracked');
select set_config('request.jwt.claim.sub',md5('campusgig:student:2')::uuid::text,true);
select lives_ok('select public.submit_work(contract_id,''https://example.com/work/final'',''Updated delivery with accessible focus indicators.'') from workflow_ids','second submission');
select set_config('request.jwt.claim.sub',md5('campusgig:client:1')::uuid::text,true);
select throws_ok('select public.request_revision(contract_id,''One additional revision request.'') from workflow_ids','P0001',null,'second revision rejected');
select lives_ok('select public.approve_work(contract_id) from workflow_ids','approve atomic release');
select is((select status from public.payments where contract_id=(select contract_id from workflow_ids)),'RELEASED','payment released');
select is((select status from public.contracts where id=(select contract_id from workflow_ids)),'COMPLETED','contract complete');
select is((select count(*)::integer from public.reputation_events where contract_id=(select contract_id from workflow_ids) and event_type='WORK_COMPLETED'),1,'one completed event');
select throws_ok('select public.approve_work(contract_id) from workflow_ids','P0001',null,'second approval rejected');
select lives_ok('select public.review_work(contract_id,5,''Excellent fictional delivery.'') from workflow_ids','review append');
select throws_ok('select public.review_work(contract_id,4,''Second review rejected.'') from workflow_ids','23505',null,'one immutable review per contract');
select is((select count(*)::integer from public.reputation_events where contract_id=(select contract_id from workflow_ids) and event_type='REVIEW_RECEIVED'),1,'one review event');
reset role;
select is((select evidence_score from public.student_skills where student_id=md5('campusgig:student:2')::uuid and skill_id=md5('campusgig:skill:react')::uuid),17,'completed skill evidence recomputed from count');
select * from finish();
rollback;